/**
 * Missions that Claude knows about (ADR-443): the glue between Mission Control and four pure modules. The context section Claude reads
 * every turn (mission-context.ts), gate evidence (mission-verify.ts), the loop manager (mission-loop.ts) and the mission's spend
 * (data/mission-cost.ts, mission-guard.ts). Nothing here reaches the network or runs anything unasked: a gate run and a loop hand-off
 * both go through the confirm row, and the loop is only ever prepared in the prompt box (Claude owns the schedule).
 */
import type { ActionSpec } from './actions'
import type { Host } from './host'
import { activeMission, derive, mcOf, nextTask, record, saveLedger } from './mission-control'
import { CONTEXT_SECTION_ID, contextEnabled, missionContextKey, missionContextText, turnNote, type TurnReason } from './mission-context'
import { armed, isTick, parseLoop, rearmCommand, startCommand, stop, stopRequest, tick, tickPlan, type LoopState } from './mission-loop'
import { evidenceEvent, parseGates } from './mission-verify'
import { costOf, capOf } from './mission-guard'
import { plain } from './data/parse'
import type { LedgerTask, MissionActions, MissionRecord } from './mission-types'
import type { Runner } from './runner'
import { settingsOf } from './settings'
import type { State } from './state'

/** The mission's loop as it was saved (validated; a bad value is no loop). */
export const loopOf = (mission: MissionRecord): LoopState | null => parseLoop(mission.loop)

const setLoop = (mission: MissionRecord, loop: LoopState): void => void (mission.loop = loop)

/** The task Claude is on, else the next ready one: what the context section describes. */
function currentTask(state: State, mission: MissionRecord): { task: LedgerTask | null; status: ReturnType<typeof derive> extends Map<string, infer S> ? S : never } {
  const tasks = state.snapshot?.tasks ?? []
  const statuses = derive(mission, tasks)
  const task = mission.tasks.find(candidate => statuses.get(candidate.id) === 'running') ?? nextTask(mission, tasks)

  return { task, status: task === null ? 'ready' : (statuses.get(task.id) ?? 'ready') }
}

let held: { key: string; text: string } | null = null

/**
 * The section `prompt.compose` adds, or null (no mission, a finished one, or the setting off). The text is rebuilt only when its key
 * changes, and the key changes only with the task: a changed system prompt makes Claude re-read the whole conversation.
 */
export function contextSection(state: State): { id: string; text: string; scope: 'session' } | null {
  const mission = activeMission(state)

  if (mission === null || !contextEnabled(settingsOf(state).ai.missionContext)) return null

  const statuses = derive(mission, state.snapshot?.tasks ?? [])

  if (mission.tasks.length > 0 && mission.tasks.every(task => statuses.get(task.id) === 'done')) return null

  const { task, status } = currentTask(state, mission)
  const loop = loopOf(mission)
  const info = loop === null || loop.status === 'idle' ? null : { interval: loop.interval, status: loop.status }
  const key = missionContextKey(mission, task, info, status)

  if (held?.key !== key) held = { key, text: missionContextText(mission, task, info, status) }

  return { id: CONTEXT_SECTION_ID, text: held.text, scope: 'session' }
}

/** A turn ended: note it on the running task (never that the task finished: the task store says that). */
export function onTurnComplete(state: State, host: Host, reason: TurnReason): void {
  const mission = activeMission(state)

  if (mission === null) return

  const running = mission.tasks.find(task => derive(mission, state.snapshot?.tasks ?? []).get(task.id) === 'running') ?? null
  const note = turnNote(reason, running)

  if (note === null) return

  record(mission, note)
  saveLedger(state, host)
}

/** A prompt was submitted: when it carries a mission's loop marker it is that loop's tick (or its first run). */
export function onPromptSubmit(state: State, host: Host, text: string): void {
  const now = Date.now()

  for (const mission of mcOf(state).missions.values()) {
    if (!isTick(text, mission.id)) continue

    const prefs = settingsOf(state).ai
    const before = loopOf(mission)
    const loop = before !== null && before.status === 'armed' ? before : armed(before, mission, before?.interval ?? prefs.loopInterval, now)
    const cost = costOf(state, mission)
    const plan = tickPlan({ mission, loop, prefs, gatesConfigured: parseGates(prefs.loopGates).gates.length > 0, spendUsd: cost?.usd ?? null, capUsd: capOf(state), nowMs: now, taskStatus: derive(mission, state.snapshot?.tasks ?? []) })

    setLoop(mission, tick(loop, now))
    record(mission, { type: 'loop.tick', note: plain(`${plan.action}: ${plan.reason}`, 200) })
    saveLedger(state, host)
    host.invalidate()
  }
}

/** The actions the Loop tab calls: verify with the person's gates, and the loop manager's start, stop and re-arm. */
export function claudeActions(state: State, host: Host, runner: Runner): Pick<MissionActions, 'verify' | 'loop'> {
  const say = (label: string, ok: boolean, detail: string) => {
    mcOf(state).last = { label, ok, detail }
    host.invalidate()
  }
  const prepare = (label: string, text: string, done: () => void): ActionSpec => ({
    label,
    scope: 'controls',
    args: [],
    shows: `in the prompt box, for you to send: “${plain(text, 160)}”`,
    expect: 'the text in Claude’s prompt box',
    note: 'Claude owns the recurring schedule; the console only prepares the text and watches the ticks. Nothing is scheduled until you press Enter there.',
    run: async () => {
      const isFilled = await host.fillPrompt(text).catch(() => false)

      if (isFilled) done()
      say(label, isFilled, isFilled ? 'prepared in the prompt box: press Enter there' : 'no prompt box to fill here')
    },
  })

  return {
    verify: () => {
      const mission = activeMission(state)
      const gates = parseGates(settingsOf(state).ai.loopGates).gates

      if (mission === null) return say('verify', false, 'no active mission')
      if (gates.length === 0) return say('verify', false, 'no gates configured: add your own commands in Settings → Mission gates')

      const { task } = currentTask(state, mission)
      const taskId = task?.id

      runner.ask(
        {
          label: `run ${gates.length} gate${gates.length === 1 ? '' : 's'}${taskId === undefined ? '' : ` for ${taskId}`}`,
          scope: 'controls',
          args: [],
          shows: gates.map(gate => gate.argv.join(' ')).join('  ·  '),
          expect: 'each gate’s exit code and a short output summary recorded as evidence on the mission',
          note: 'Runs the commands you configured, one after another, without a shell, in this project. Their output is evidence; nothing is changed by the console.',
          run: async () => {
            let failed = 0

            for (const gate of gates) {
              const result = await host.run(gate.argv, 180_000).catch(() => null)

              record(mission, evidenceEvent(gate, result === null ? { exitCode: null, stdout: '', stderr: '' } : { exitCode: result.exitCode ?? null, stdout: result.stdout, stderr: result.stderr }, taskId))
              if (result === null || result.exitCode !== 0) failed += 1
            }

            saveLedger(state, host)
            say('gates', failed === 0, failed === 0 ? `all ${gates.length} passed` : `${failed} of ${gates.length} did not pass: see Evidence`)
          },
        },
        'nothing to run',
      )
    },
    loop: {
      start: () => {
        const mission = activeMission(state)

        if (mission === null) return say('loop', false, 'no active mission')

        const prefs = settingsOf(state).ai
        const interval = loopOf(mission)?.interval ?? prefs.loopInterval

        runner.ask(prepare('start the mission loop', startCommand(mission, prefs, interval), () => record(mission, { type: 'loop.prepared', note: `/loop ${interval}` })), 'no active mission')
      },
      stop: () => {
        const mission = activeMission(state)
        const loop = mission === null ? null : loopOf(mission)

        if (mission === null || loop === null) return say('loop', false, 'no loop to stop')

        runner.ask(prepare('ask Claude to stop the mission loop', stopRequest(loop, mission), () => {
          setLoop(mission, stop(loop))
          record(mission, { type: 'loop.stop-requested' })
          saveLedger(state, host)
        }), 'no loop to stop')
      },
      rearm: () => {
        const mission = activeMission(state)
        const loop = mission === null ? null : loopOf(mission)
        const command = mission === null ? null : rearmCommand(loop, mission, settingsOf(state).ai, Date.now())

        if (mission === null || command === null) return say('loop', false, 'the loop is not stopped, expired or overdue')

        runner.ask(prepare('re-arm the mission loop', command, () => record(mission, { type: 'loop.rearm-prepared' })), 'nothing to re-arm')
      },
    },
  }
}

files.hooks/updates.ts:
/**
 * Updates, pure: when a newer ruflo-console is published to github.com/ruvnet/ruflo, offer it at load, and keep an "always" choice.
 * Versions, the published manifest, the rules for what to do (ask, update without asking, leave alone), the question, and a read of
 * `claude plugin list --json` live here with no host and no network, so tests/updates.spec.ts runs them. The flow that fetches and
 * installs is hooks/update-flow.ts. The install itself is Claude Code's own `claude plugin update`, never code of ours, and its own
 * confirmation for a marketplace-declared command is never bypassed (no `-y`, no `--accept-command`).
 */
import { RUFLO_MARKET } from './data/snapshot'

export type UpdatesMode = 'ask' | 'auto' | 'off'
export const UPDATES_MODES: readonly UpdatesMode[] = ['ask', 'auto', 'off']

export const parseMode = (value: unknown): UpdatesMode => (value === 'auto' || value === 'off' ? value : 'ask')

/** Keys in the plugin's store (shared across sessions): the mode, when it last checked, when a session began updating, what it installed. */
export const UPDATES_KEY = 'updates'
export const CHECKED_KEY = 'update-checked-at'
export const APPLYING_KEY = 'update-applying-at'
export const INSTALLED_KEY = 'update-installed'

export const PLUGIN_NAME = 'ruflo-console'
/** The marketplace the plugin is installed from (`claude plugin marketplace list`: ruflo, GitHub ruvnet/ruflo). */
export const MARKET = RUFLO_MARKET
export const PLUGIN_ID = `${PLUGIN_NAME}@${MARKET}`
/** The published manifest: the same repository the ruflo marketplace is added from (ruvnet/ruflo), its main branch. */
export const MANIFEST_URL = 'https://raw.githubusercontent.com/ruvnet/ruflo/main/plugins/ruflo-console/.claude-plugin/plugin.json'
/** How often a session checks (the answer is cached across sessions), and how long one session's "I am updating" holds the others off. */
export const CHECK_EVERY_MS = 24 * 60 * 60_000
/** A session left open re-asks on this timer; the daily gate above still decides whether the network is touched. */
export const RECHECK_EVERY_MS = 6 * 60 * 60_000
/** The newest version a quiet re-check already told this person about, so a long session toasts once, not every tick. */
export const NOTIFIED_KEY = 'ruflo-console/update-notified'
export const APPLYING_HOLD_MS = 10 * 60_000

export const LABEL = { now: 'Update now', always: 'Always auto-update', later: 'Not now' } as const

/** The command to type by hand, said whenever Claude Code asks for its own confirmation or the update cannot be done from here. */
export const MANUAL_COMMAND = `claude plugin update ${PLUGIN_ID}`

type Semver = readonly [number, number, number]

/** `major.minor.patch` and nothing else: a pre-release or build suffix is never offered. */
export function parseSemver(text: string): Semver | null {
  const match = /^(\d{1,4})\.(\d{1,4})\.(\d{1,4})$/.exec(text.trim())

  return match === null ? null : [Number(match[1]), Number(match[2]), Number(match[3])]
}

export type Bump = 'patch' | 'minor' | 'major'

/** What `remote` is over `local`, or null when it is not strictly newer (the same, older, or not a version): never a downgrade. */
export function bumpKind(local: string, remote: string): Bump | null {
  const a = parseSemver(local)
  const b = parseSemver(remote)

  if (a === null || b === null) return null
  if (b[0] !== a[0]) return b[0] > a[0] ? 'major' : null
  if (b[1] !== a[1]) return b[1] > a[1] ? 'minor' : null

  return b[2] > a[2] ? 'patch' : null
}

/** The version in a fetched manifest, only if it is ours (`name` is ruflo-console) and a plain semver; else null. */
export function versionFromManifest(text: string): string | null {
  try {
    const value = JSON.parse(text) as { name?: unknown; version?: unknown }

    return value.name === PLUGIN_NAME && typeof value.version === 'string' && parseSemver(value.version) !== null ? value.version.trim() : null
  } catch {
    return null
  }
}

/** Time to check: never has, a day has passed, or the stored time is in the future (a clock that moved). */
export const isDue = (lastMs: unknown, nowMs: number): boolean => typeof lastMs !== 'number' || !Number.isFinite(lastMs) || lastMs > nowMs || nowMs - lastMs >= CHECK_EVERY_MS

/** Another session began updating a moment ago: this one leaves it alone (best effort; the store is not atomic). */
export const isBeingApplied = (startedMs: unknown, nowMs: number): boolean => typeof startedMs === 'number' && Number.isFinite(startedMs) && startedMs <= nowMs && nowMs - startedMs < APPLYING_HOLD_MS

export type Decision = 'none' | 'ask' | 'auto'

/**
 * What to do with a newer version. Off does nothing. Auto updates without asking, but never across a major version: a new major can
 * change what the console does, so it always asks. Otherwise it asks.
 */
export function decide(mode: UpdatesMode, kind: Bump | null): Decision {
  if (kind === null || mode === 'off') return 'none'

  return mode === 'auto' && kind !== 'major' ? 'auto' : 'ask'
}

/**
 * The question and the choices. "Always" is offered only below a major version, and says exactly what it means; the question ends
 * in a question mark, as the dialog requires.
 */
export function promptOf(local: string, remote: string, kind: Bump): { question: string; options: string[] } {
  const intro = `ruflo-console ${remote} is published to github.com/ruvnet/ruflo (you have ${local}${kind === 'major' ? '; a new major version, which can change what the console does' : ''}).`
  const always = kind === 'major' ? '' : `\n\n"${LABEL.always}" installs every new minor or patch version published there without asking (a new major version always asks). You can turn it off in Settings.`
  const how = '\n\nIt runs claude plugin marketplace update, then claude plugin update, and takes effect after you restart Claude Code or run /reload-plugins.'

  return { question: `${intro}${always}${how}\n\n${LABEL.now}?`, options: kind === 'major' ? [LABEL.now, LABEL.later] : [LABEL.now, LABEL.always, LABEL.later] }
}

export type Installed = { version: string; scope: string }

/**
 * Every install of ours that applies to a session working in `cwd`: the user-scope one, and a project or local one whose project is
 * `cwd` or holds it. An install for another project does not load here, so it is never touched. If none of those is found but the plugin
 * is listed, the single entry `installedEntry` would pick stands in (an unusual layout still gets an update, not a refusal).
 */
export function installedEntries(listJson: string, cwd: string, id: string = PLUGIN_ID): Installed[] {
  try {
    const list = JSON.parse(listJson) as unknown

    if (!Array.isArray(list)) return []

    const ours = list.filter((entry): entry is { id: string; version?: unknown; scope?: unknown; projectPath?: unknown } => typeof entry === 'object' && entry !== null && (entry as { id?: unknown }).id === id)
    const here = (entry: { projectPath?: unknown }) => typeof entry.projectPath === 'string' && entry.projectPath !== '' && (cwd === entry.projectPath || cwd.startsWith(`${entry.projectPath.replace(/\/+$/, '')}/`))
    const applies = ours.filter(entry => entry.scope === 'user' || ((entry.scope === 'project' || entry.scope === 'local') && here(entry)))
    const valid = applies.flatMap(entry => (typeof entry.version === 'string' && typeof entry.scope === 'string' ? [{ version: entry.version, scope: entry.scope }] : []))

    if (valid.length > 0) return valid

    const single = installedEntry(listJson, id)

    return single === null ? [] : [single]
  } catch {
    return []
  }
}

/**
 * Our plugin in `claude plugin list --json`: the user-scope entry if there is one, else an enabled one, else the first. Null when it is
 * not installed from the marketplace (a session loaded with --plugin-dir has nothing to update) or the output is not the list.
 */
export function installedEntry(listJson: string, id: string = PLUGIN_ID): Installed | null {
  try {
    const list = JSON.parse(listJson) as unknown

    if (!Array.isArray(list)) return null

    const ours = list.filter((entry): entry is { id: string; version?: unknown; scope?: unknown; enabled?: unknown } => typeof entry === 'object' && entry !== null && (entry as { id?: unknown }).id === id)
    const chosen = ours.find(entry => entry.scope === 'user') ?? ours.find(entry => entry.enabled === true) ?? ours[0]

    return chosen === undefined || typeof chosen.version !== 'string' || typeof chosen.scope !== 'string' ? null : { version: chosen.version, scope: chosen.scope }
  } catch {
    return null
  }
}

/** Claude Code refuses to run a marketplace-declared command unattended and says so: that is its trust gate, not a failure to retry. */
export const needsConfirmation = (output: string): boolean => /shownCommand|must be confirmed|confirm/i.test(output)

/** One short line of a command's output, for the toast: escapes and control characters removed, cut to fit. */
export function firstLine(text: string, max = 140): string {
  const line =
    text
      .replace(/\x1b\[[0-9;?]*[ -/]*[@-~]/g, '')
      .split('\n')
      .map(entry => entry.replace(/[\u0000-\u001f\u007f‪-‮]/g, '').trim())
      .find(entry => entry !== '') ?? ''

  return line.length > max ? `${line.slice(0, max - 1)}…` : line
}

files.hooks/self-check.ts:
/**
 * The console's self-check, pure and spawn-free: for every area the boot log names, does what a press would run still resolve
 * to a well-formed command? It reads the same registries the buttons read (Security, Performance, Dev Tools, the MetaHarness
 * lab), so a verb whose argv is empty, whose text field accepts what its rule forbids, or whose documented input is refused is
 * caught here, not by a person pressing it. It does not run the CLI: that every command is built right is proved here, that the CLI
 * answers is the Doctor's job. The boot log shows these results, so an `[ OK ]` on screen means this passed for that area.
 * Tested in tests/self-check.spec.ts, including that a broken entry fails (so a pass is not vacuous).
 */
import { VIEW_ASK } from './ask-claude'
import { emptyFields, type DevFields } from './data/devtools'
import { DEV, type DevEntry } from './devtools'
import { BOOT_MODULES } from './gfx/boot'
import { LAB, type LabEntry } from './mh-lab'
import { PERF, type PerfEntry } from './perf'
import { SECURE, SECURE_TEXT, type SecEntry, type SecText } from './secure'
import { newState, VIEWS, type State, type ViewId } from './state'

export type CheckResult = { area: string; ok: boolean; checked: number; problems: string[] }

/** Each boot area and the page it opens: every area must name a real page, and the spec fails on an area with no row here. */
export const AREA_VIEW: Record<string, ViewId> = {
  Missions: 'missions', Overview: 'overview', Swarm: 'swarm', 'Hive-Mind': 'hive', Claims: 'claims', Approvals: 'approvals', Automation: 'automate',
  Learning: 'learning', Neural: 'neural', 'Vector Lab': 'vector', 'Memory Lab': 'memory', MetaHarness: 'metaharness', 'Self-Evolution': 'evolve',
  Security: 'secure', Federation: 'federation', 'x.ruv.io': 'xruv', 'Plugins & Mods': 'plugins', Skills: 'skills', 'Plugin Catalog': 'market',
  'Dev Tools': 'devtools', Sandbox: 'sandbox', 'Cost & Budget': 'cost', Timeline: 'timeline', Events: 'events', 'The Room': 'room', Performance: 'perf', 'AI Terminal': 'terminal', Settings: 'settings',
}

/** Pages with no hotkey on purpose (every letter is taken): reached from the menu, the nav, the palette or by name. */
const NAMED_ONLY: ReadonlySet<string> = new Set(['sandbox', 'room'])

export type Registries = { secure: readonly SecEntry[]; secureText: readonly SecText[]; perf: readonly PerfEntry[]; dev: readonly DevEntry[]; lab: readonly LabEntry[] }
export const REGISTRIES: Registries = { secure: SECURE, secureText: SECURE_TEXT, perf: PERF, dev: DEV, lab: LAB }

/** One value per field that its rule accepts, so every runnable Dev Tools row has an input that runs. */
export const SAMPLE_FIELDS: DevFields = { ref: 'HEAD~1', path: 'memory/sample.rvf', label: 'ckpt-1', url: 'https://example.com', target: '@e1', query: 'auth', task: 'review my pull request', cmd: 'ls', id: 'agent-1', note: 'hello', session: 'demo', send: 'ls -la' }

/** Free text, then an action type (policy-eval takes one): a text verb passes when any of these builds its command. */
const SAMPLE_TEXTS = ['hello world', 'deploy']
const isArgv = (value: unknown): value is readonly string[] => Array.isArray(value) && value.length > 0 && value.every(part => typeof part === 'string' && part !== '' && !/[\u0000-\u001f]/.test(part))

function checkArgs(id: string, args: unknown, problems: string[]): void {
  if (!isArgv(args)) problems.push(`${id}: its command is empty or has an empty or control-character part`)
}

function checkSecure(entries: readonly SecEntry[], text: readonly SecText[], perf: readonly PerfEntry[], problems: string[]): number {
  for (const entry of [...entries, ...perf]) {
    checkArgs(entry.id, entry.args, problems)
    if (typeof entry.read !== 'function') problems.push(`${entry.id}: nothing reads its output`)
    if (entry.label.trim() === '') problems.push(`${entry.id}: no label for the confirm row`)
  }

  for (const entry of text) {
    const empty = entry.argv('')
    const sample = SAMPLE_TEXTS.find(candidate => isArgv(entry.argv(candidate)))

    if (empty !== null) problems.push(`${entry.id}: an empty field must be refused, but it builds a command`)
    if (entry.argv('-rf') !== null) problems.push(`${entry.id}: text starting with - must be refused (it could be read as a flag)`)
    if (sample === undefined) problems.push(`${entry.id}: no sample input (${SAMPLE_TEXTS.join(', ')}) builds its command, so its button can never run`)
    else if (!(entry.argv(sample) ?? []).some(part => part.includes(sample))) problems.push(`${entry.id}: the text does not reach the command`)
    if (typeof entry.read !== 'function') problems.push(`${entry.id}: nothing reads its output`)
  }

  return entries.length + text.length + perf.length
}

function checkDev(entries: readonly DevEntry[], problems: string[]): number {
  for (const entry of entries) {
    if (entry.na !== undefined) {
      if (entry.na.trim() === '') problems.push(`${entry.id}: marked n/a with no reason to show`)

      continue
    }

    const build = entry.exec ?? entry.args

    if (build === undefined) {
      problems.push(`${entry.id}: it is neither runnable nor marked n/a`)

      continue
    }

    const bare = build(emptyFields())

    // With no field needed, an empty page must already run; with one, an empty field may be refused, but the sample must run.
    if (bare === null && entry.input === undefined) problems.push(`${entry.id}: it names no input field, yet cannot run on an empty page`)

    const sampled = build(SAMPLE_FIELDS)

    if (!isArgv(sampled)) problems.push(`${entry.id}: no input is accepted, so its button can never run`)
  }

  return entries.length
}

function checkLab(entries: readonly LabEntry[], state: State, problems: string[]): number {
  for (const entry of entries) {
    const args = typeof entry.args === 'function' ? entry.args(state) : entry.args

    if (args === undefined && entry.types === undefined) problems.push(`${entry.id}: no command and no command to type`)
    else if (args === null) {
      if ((entry.why ?? '').trim() === '') problems.push(`${entry.id}: it cannot run now and says nothing about why`)
    } else if (args !== undefined) checkArgs(entry.id, args, problems)
  }

  return entries.length
}

function checkUnique(registries: Registries, problems: string[]): void {
  const seen = new Set<string>()

  for (const id of [...registries.secure, ...registries.secureText, ...registries.perf, ...registries.dev, ...registries.lab].map(entry => entry.id)) {
    if (seen.has(id)) problems.push(`${id}: used by two entries (ids are palette keywords)`)
    seen.add(id)
  }
}

/**
 * One result per boot area, in boot order. Every area has its page checked (it exists, has a key, and has an Ask row); the areas that
 * own a command registry have each command checked too. `problems` names what is wrong, so the boot log can say what failed.
 */
export function selfCheck(registries: Registries = REGISTRIES, views: readonly { id: string; key: string }[] = VIEWS, ask: Record<string, unknown> = VIEW_ASK): CheckResult[] {
  const state = newState(undefined)
  const shared: string[] = []

  checkUnique(registries, shared)

  return BOOT_MODULES.map(({ name }): CheckResult => {
    const problems: string[] = []
    const view = AREA_VIEW[name]
    let checked = 1

    if (view === undefined) problems.push(`${name}: no page is named for this area`)
    else {
      if (!views.some(entry => entry.id === view)) problems.push(`${name}: its page "${view}" does not exist`)
      if (!views.some(entry => entry.id === view && (entry.key !== '' || NAMED_ONLY.has(entry.id)))) problems.push(`${name}: its page has no key`)
      if (ask[view] === undefined) problems.push(`${name}: its page has no Ask Claude row`)
    }

    if (name === 'Security') checked += checkSecure(registries.secure, registries.secureText, [], problems)
    if (name === 'Performance') checked += checkSecure([], [], registries.perf, problems)
    if (name === 'Dev Tools') checked += checkDev(registries.dev, problems)
    if (name === 'MetaHarness') checked += checkLab(registries.lab, state, problems)
    // Ids are palette keywords shared by all four registries, so a duplicate fails each area that owns one of them.
    if (['Security', 'Performance', 'Dev Tools', 'MetaHarness'].includes(name)) problems.push(...shared)

    return { area: name, ok: problems.length === 0, checked, problems }
  })
}

let held: CheckResult[] | null = null

/** The real registries' results, computed once: the boot log reads these every frame. */
export function selfCheckResults(): CheckResult[] {
  held ??= selfCheck()

  return held
}

files.hooks/views/common.ts:
/**
 * Shared drawing helpers. Views are pure: `(ctx) => tree`, built from the surface's element table, reading the state
 * and the pictures computed for this frame. They call nothing on the engine; buttons call the closures in `ctx.act`.
 * Text colours are theme names only, so nothing fades on a light background.
 */
import type { AskActions } from '../ask-claude'
import type { OptimizerActions } from '../optimizer'
import { askedBy } from '../data/room'
import type { RoomActions } from '../room'
import type { WatchActions } from '../watch'
import type { Attention } from './attention'
import { HEADS, mark as marked } from './marks'
import type { LoopActions } from '../loops'
import type { Elements, RenderChildren, RenderElement } from 'claude-code'

import type { ProbeResult } from '../data/cli'
import type { EvolveActions } from '../evolve'
import type { MissionActions } from '../mission-control'
import type { CatalogActions } from '../plugin-catalog'
import type { SettingsActions } from '../settings'
import type { DevtoolsActions } from '../devtools'
import type { Grid } from '../gfx/raster'
import type { MemoryActions } from '../memory-lab'
import type { NavActions } from '../nav-state'
import type { SkillActions } from '../skills'
import type { HelpActions } from '../help-actions'
import type { PluginOp } from '../plugin-ops'
import { START_LABEL, type StartId } from '../starts'
import type { MoreSkillActions } from '../skills-lab'
import { VIEWS, type HarnessId, type NavStyle, type State, type ViewId } from '../state'
import type { UpdatesMode } from '../updates'
import { chip, COST_CHIP } from '../menu-colors'
import { accentOfView } from '../nav-state'
import type { VectorActions } from '../vector'

export type Kit = Pick<Elements['terminal'], 'Box' | 'Text' | 'Button'> & { Raster?: Elements['terminal']['Raster']; Input?: Elements['terminal']['Input'] }

/** What a button can ask for: every one a closure over the controller. */
export type Actions = {
  view: (id: ViewId) => void
  refresh: () => void
  /** Refresh and replay the intro boot screen: the footer button and the r key. */
  restart: () => void
  help: () => void
  close: () => void
  back: () => void
  confirm: () => void
  cancel: () => void
  /** j/k: moves the selection of the view in front. */
  select: (by: number) => void
  agentNext: () => void
  taskNext: () => void
  /** Drills into the selected agent. */
  drill: () => void
  claim: () => void
  release: () => void
  handoff: () => void
  steal: () => void
  palette: (context: 'all' | 'selection') => void
  paletteQuery: (text: string) => void
  paletteRun: (id: string) => void
  paletteSubmit: () => void
  run: (id: string, text?: string) => boolean
  costBudgetDraft: (text: string) => void
  /** Cycles the events view's filter. */
  filter: () => void
  /** The terminal view: pick a harness, follow the field, ask to run its text, stop the run, clear the scrollback. */
  /** A one-click start for an empty section (init, swarm, hive, workers…): asks, runs, and re-reads the disk. */
  /** Puts the keys in one of the pane's fields by its key (a row that takes text focuses its field). */
  focus: (key: string) => void
  start: (id: StartId, text?: string) => void
  /** The marketplace update on the Plugins and Plugin Catalog pages: asks first, then runs one `claude plugin` command. */
  plugin: (op: PluginOp) => void
  /** The main menu's prompt: a key or a name takes the person to that area. */
  menu: (text: string) => void
  term: { harness: (id: HarnessId) => void; draft: (text: string) => void; submit: (text: string) => void; stop: () => void; fresh: () => void; clear: () => void; load: (id: HarnessId, text: string) => void; /** A click on an ask link: opens the terminal, picks the agent and sends the text at once (read-only, plan mode, the saved per-turn budget): the reply streams in with no second click. */ ask: (id: HarnessId, text: string) => void; /** Moves the window up (positive) or down by screen rows. */ scroll: (by: number) => void; /** Puts an earlier question back in the field. */ reuse: (text: string) => void }
  /** The skills view: list, search, and the confirm-gated add, remove, update and create; edit loads the terminal. */
  skills: SkillActions & MoreSkillActions
  /** The Memory Lab: its fields, search, browse filter, and an entry's open or delete (each through the runner). */
  memory: MemoryActions
  /** The Vector Lab: its fields, its entries (asked or run through the runner), and rvlite queries handed to the terminal. */
  vector: VectorActions
  /** The Self-Evolution view: read its files again; ▸ ask types a repo prompt into the AI terminal. */
  evolve: EvolveActions
  /** The Dev Tools view: keep a field's text, and Enter in a field runs its entry. */
  devtools: DevtoolsActions
  /** The Loop Manager (Automation): presets, the configurator, and the launcher into the Claude UI. */
  loops: LoopActions
  /** The Optimizer (Overview): scope, fixes (each asks first) and asking Claude about a finding. */
  optimizer: OptimizerActions
  /** The Timeline and Events pages: look-back range, kind filter, search, pause, paging, an event's detail, and asking about one. */
  watch: WatchActions
  /** The Room (ADR-448): the draft, what to send through, the feed's source filter, search, pause and paging. */
  room: RoomActions
  /** Ask Claude about this section (a visible prompt or a /btw aside) or run the plugin command that fits it: each asks first. */
  ask: AskActions
  /** ruHelp, the built-in help: a question, a guide, a step's button, and asking Claude with the docs. */
  ruhelp: HelpActions
  /** Mission Control: goal, profile, create, run next, pause/resume/cancel, auto-run, ask aside, guide Claude. */
  mission: MissionActions
  /** Claude's control of the console (ADR-444): the person takes it back, or gives it back. */
  control: { pause: (on: boolean) => void }
  /** The Plugin Catalog: read the clone, filter, select a plugin, view or use an item, change a plugin (each asks first). */
  catalog: CatalogActions
  /** Puts text back in an entry field and gives it the keys, so what was entered can be edited and sent again. */
  editField: (key: string, text: string) => void
  /** Empties an entry field after its Enter. */
  clearField: (key: string) => void
  /** The confirm row's "always allow this kind of action": remembers the kind (Settings forgets it) and runs the pending ask. */
  remember: () => void
  /** Forgets one remembered kind of action, or all of them (an empty key). */
  forget: (key: string) => void
  /** The nav card: show a group's pages, search the pages, clear the search. */
  navigator: NavActions
  /** Sets how the main nav spells its tabs (saved). */
  nav: (style: NavStyle) => void
  /** Sets whether to check for a newer published ruflo-console: ask first, update without asking, or never (saved). */
  updates: (mode: UpdatesMode) => void
  /** Checks now, whatever the daily gate or an off setting says (it still asks before installing, and skips a development checkout). */
  checkUpdates: () => void
  /** Opens or closes a collapsible section (`<view>/<id>`). */
  toggle: (key: string) => void
  /** Settings: the level, a plugin, an option or ruflo config change (each asks first), AI preferences, and ▸ ask claude/codex. */
  settings: SettingsActions
}

export type Ctx = {
  kit: Kit
  state: State
  nowMs: number
  columns: number
  /** Every picture of this view, by Raster key, already drawn for this frame. */
  pictures: Map<string, Grid>
  act: Actions
  /** True while the page is drawn in cards (views/card.ts): a section header then needs no blank row above it. */
  cards?: boolean
  /** The page's attention panel (views/attention.ts): lab views hand their result rows to it with `slot`. */
  attention?: Attention
}

export type Look = 'bbs' | 'plain'

/** The terminal theme's own colours: readable on light and dark backgrounds alike. */
const PLAIN = { head: 'claude', ok: 'success', bad: 'error', warn: 'warning', info: 'suggestion' }
/** The BBS look: neon magenta headings, cyan values, matrix-green labels; amber stays for attention. */
const NEON = { head: '#ff2a6d', ok: '#39ff14', bad: '#ff3355', warn: '#ffd319', info: '#05d9e8' }
const NEON_LABEL = '#2fbf71'

/** The palette every view reads; `setLook` swaps it in place before a render, so callers keep using THEME.x. */
export const THEME: { head: string; ok: string; bad: string; warn: string; info: string } = { ...PLAIN }
let look: Look = 'plain'

export function setLook(next: Look): void {
  if (next === look) return
  look = next
  Object.assign(THEME, next === 'bbs' ? NEON : PLAIN)
}

export const isBbs = (): boolean => look === 'bbs'

/**
 * A cost tag (`$0`, `wr`, `net`, `$$`) on a run row. In the BBS look it is a solid chip, the way the menu draws a key: the ink on a ground
 * by how much the run asks (a read green, local work or a write cyan, the network amber, spending or deleting red). In the plain look it
 * is coloured text, as it always was. `color` is the tag's theme colour; a colour that is none of the four stays text.
 */
export function tagChip(ctx: Ctx, text: string, color: string): RenderElement {
  const ground = look !== 'bbs' ? undefined : color === THEME.ok ? COST_CHIP.ok : color === THEME.info ? COST_CHIP.info : color === THEME.warn ? COST_CHIP.warn : color === THEME.bad ? COST_CHIP.bad : undefined

  if (ground === undefined) return ctx.kit.Text({ bold: true, color, children: ` ${text}` })

  return ctx.kit.Box({ flexDirection: 'row', children: [ctx.kit.Text({ children: ' ' }), ctx.kit.Text({ ...chip(ground), children: text })] })
}

/** Words wrapped to `width`, so a long line reads as several instead of running off the edge. */
export function wrap(line: string, width: number): string[] {
  const out: string[] = []
  let current = ''

  for (const word of line.split(' ')) {
    if (current !== '' && current.length + word.length + 1 > width) {
      out.push(current)
      current = word
    } else current = current === '' ? word : `${current} ${word}`
  }

  return current === '' ? out : [...out, current]
}

export const clip = (text: string, width: number): string => (text.length <= width ? text : `${text.slice(0, Math.max(0, width - 1))}…`)

export function ago(atMs: number | null | undefined, nowMs: number): string {
  if (atMs === null || atMs === undefined || !Number.isFinite(atMs)) return 'n/a'

  const s = Math.max(0, Math.round((nowMs - atMs) / 1000))

  if (s < 60) return `${s}s ago`
  if (s < 3600) return `${Math.floor(s / 60)}m ago`
  if (s < 86_400) return `${Math.floor(s / 3600)}h ago`

  return `${Math.floor(s / 86_400)}d ago`
}

/** A count as people read it (12.3k), or n/a for a value nobody measured. */
export function count(value: number | null | undefined): string {
  if (value === null || value === undefined || !Number.isFinite(value)) return 'n/a'
  if (Math.abs(value) >= 1_000_000) return `${(value / 1_000_000).toFixed(1)}M`
  if (Math.abs(value) >= 10_000) return `${(value / 1000).toFixed(1)}k`

  return String(Math.round(value * 100) / 100)
}

export const pct = (value: number | null | undefined): string => (value === null || value === undefined || !Number.isFinite(value) ? 'n/a' : `${Math.round(value * 100)}%`)

export function text(ctx: Ctx, children: string, props: { color?: string; bold?: boolean; dimColor?: boolean; italic?: boolean } = {}): RenderElement {
  return ctx.kit.Text({ wrap: 'truncate-end', ...props, children: clip(children, Math.max(4, ctx.columns)) })
}

export function row(ctx: Ctx, parts: readonly RenderChildren[], key?: string): RenderElement {
  return ctx.kit.Box({ flexDirection: 'row', ...(key !== undefined && { key }), children: [...parts] })
}

export function col(ctx: Ctx, parts: readonly RenderChildren[], key?: string): RenderElement {
  return ctx.kit.Box({ flexDirection: 'column', ...(key !== undefined && { key }), children: [...parts] })
}

/** The colour a BBS page's section headers wear: the accent of its nav group (the menu's colours), else the theme's. Plain look: the theme's. */
function accentOf(ctx: Ctx): string {
  return look === 'bbs' ? (accentOfView(ctx.state.view === 'agent' ? ctx.state.back : ctx.state.view) ?? THEME.info) : THEME.info
}

/**
 * A collapsible section: its header is a button (▾ open, ▸ closed) and the rows follow only while it is open. `open` is the
 * section's default; pressing the header flips it for this session. The header reads as `rule` does.
 */
export function section(ctx: Ctx, id: string, title: string, right: string, children: readonly RenderElement[], isOpenByDefault = true): RenderElement[] {
  const key = `${ctx.state.view}/${id}`
  const isOpen = isOpenByDefault !== ctx.state.sections.has(key)
  const mark = isOpen ? '▾' : '▸'
  const head = look === 'bbs' ? `▓▒░ ${mark} ${title.toUpperCase()} ░▒▓` : `${mark} ${title}`
  const fill = Math.max(1, ctx.columns - head.length - right.length - 2)

  return [
    ...(look === 'bbs' && ctx.cards !== true ? [ctx.kit.Text({ children: ' ' })] : []),
    marked(
      HEADS,
      row(
        ctx,
        [
          ctx.kit.Button({ key: `sec-${id}`, label: head, plain: true, onPress: () => ctx.act.toggle(key) }),
          ctx.kit.Text({ color: accentOf(ctx), dimColor: true, children: `${(look === 'bbs' ? '═' : '─').repeat(fill)} ` }),
          ctx.kit.Text({ color: accentOf(ctx), children: right }),
        ],
        `sec-row-${id}`,
      ),
    ),
    ...(isOpen ? children : []),
  ]
}

/** A section title with a rule to the right edge. */
export function rule(ctx: Ctx, title: string, right = ''): RenderElement {
  if (look === 'bbs') {
    // BBS section header: ▓▒░ SWARM ░▒▓══════════ right
    const head = `▓▒░ ${title.toUpperCase()} ░▒▓`
    const fill = Math.max(1, ctx.columns - head.length - right.length - 2)

    const line = row(ctx, [ctx.kit.Text({ bold: true, color: accentOf(ctx), children: head }), ctx.kit.Text({ color: accentOf(ctx), dimColor: true, children: `${'═'.repeat(fill)} ` }), ctx.kit.Text({ color: accentOf(ctx), children: right })])

    // In a card the header is the card's first row; otherwise a blank line above each section, so the board breathes instead of packing every block together.
    return ctx.cards === true ? marked(HEADS, line) : marked(HEADS, col(ctx, [ctx.kit.Text({ children: ' ' }), line]))
  }

  const fill = Math.max(1, ctx.columns - title.length - right.length - 3)

  return marked(HEADS, row(ctx, [ctx.kit.Text({ bold: true, color: THEME.head, children: title }), ctx.kit.Text({ dimColor: true, children: ` ${'─'.repeat(fill)} ` }), ctx.kit.Text({ dimColor: true, children: right })]))
}

/** A label and its value; the value dims when it is n/a. */
export function kv(ctx: Ctx, label: string, value: string, color?: string): RenderElement {
  const isNa = value === 'n/a' || value.startsWith('n/a ') || value === 'missing'

  // BBS: green labels and cyan values, the way a sysop screen lists its stats.
  const neonValue = look === 'bbs' && color === undefined ? { color: THEME.info } : {}

  return row(ctx, [
    // BBS rows sit indented one column, with two spaces between label and value.
    ctx.kit.Text(look === 'bbs' ? { color: NEON_LABEL, children: ` ${label.padEnd(16)}  ` } : { dimColor: true, children: `${label.padEnd(16)} ` }),
    ctx.kit.Text({ wrap: 'truncate-end', ...(isNa ? { dimColor: true } : color !== undefined ? { color } : neonValue), children: clip(value, Math.max(4, ctx.columns - (look === 'bbs' ? 20 : 18))) }),
  ])
}

/** A Raster for a picture of this frame, or a dim note where the surface has no Raster. */
export function picture(ctx: Ctx, key: string, fallback: string): RenderElement {
  const grid = ctx.pictures.get(key)

  if (grid === undefined || ctx.kit.Raster === undefined) {
    return text(ctx, fallback, { dimColor: true })
  }

  return ctx.kit.Raster(grid.toRaster(key))
}

export function button(ctx: Ctx, key: string, label: string, onPress: () => void, options: { hotkey?: string; primary?: boolean } = {}): RenderElement {
  return ctx.kit.Button({ key, label, onPress, ...(options.hotkey !== undefined && { hotkey: options.hotkey }), ...(options.primary === true && { variant: 'primary' as const }) })
}

/** A start that takes a sentence (a task, a mission objective): a text field whose Enter asks, with the confirm after. */
export function startField(ctx: Ctx, id: StartId, placeholder: string): RenderElement {
  return ctx.kit.Input === undefined
    ? text(ctx, ` ${START_LABEL[id]}: this surface has no text field (/ruflo run ${id} <text>)`, { dimColor: true })
    : ctx.kit.Input({ key: `start-field-${id}`, label: START_LABEL[id], placeholder, submitLabel: 'ask', onSubmit: value => ctx.act.start(id, value) })
}

/**
 * What an empty section offers instead of a command to copy: a line saying what is missing, then a button per start
 * (each asks first, with the exact command on the confirm row, and the view fills in once it has run).
 */
export function starts(ctx: Ctx, why: string, ids: readonly StartId[], scope = ''): RenderElement {
  return col(ctx, [
    text(ctx, ` ${why}`, { color: THEME.warn }),
    row(ctx, [text(ctx, ' '), ...ids.map(id => button(ctx, `start-${scope}${id}`, `▸ ${START_LABEL[id]}`, () => ctx.act.start(id)))]),
  ])
}

/** How a CLI-sourced fact reads: its value's age, running, failing with a stale value, or never measured. */
export function sourceLine(result: ProbeResult | undefined, nowMs: number, what: string): { text: string; color?: string } {
  if (result === undefined || (result.okAtMs === null && result.error === null)) {
    return { text: result?.isRunning === true ? `${what}: asking the ruflo CLI…` : `${what}: not asked yet` }
  }

  if (result.error !== null && (result.errorAtMs ?? 0) >= (result.okAtMs ?? 0)) {
    return { text: `${what}: ${clip(result.error, 80)}${result.okAtMs !== null ? ` (last good ${ago(result.okAtMs, nowMs)}, not shown as live)` : ''}`, color: THEME.warn }
  }

  return { text: `${what}: ruflo CLI, ${ago(result.okAtMs, nowMs)}` }
}

/** The value of a probe only while it is the newest answer: a value older than the latest failure is stale. */
export function live<T>(result: ProbeResult | undefined): T | null {
  if (result === undefined || result.value === null) return null
  if (result.error !== null && (result.errorAtMs ?? 0) >= (result.okAtMs ?? 0)) return null

  return result.value as T
}

/**
 * The ask a click or an Enter raised, with the exact command, its note, and Yes / Cancel (and the remember choices). A view
 * in INLINE_CONFIRM draws it itself, right under the field the person typed in; every other view gets it above its body.
 * `scope` is where the ask came from: a view draws only the asks that belong under its own fields.
 */
export function confirmRow(ctx: Ctx): RenderElement | null {
  const pending = ctx.state.pending

  if (pending === null) return null

  // An ask belongs to the page that raised it: anywhere else it is one line, with a way there and a way to drop it.
  if (pending.view !== undefined && pending.view !== ctx.state.view) {
    const where = VIEWS.find(entry => entry.id === pending.view)

    return row(
      ctx,
      [
        text(ctx, `⚠ An ask is waiting on ${where?.label ?? pending.view}: ${clip(askedBy(pending) + pending.label, Math.max(16, ctx.columns - 64))} `, { bold: true, color: THEME.warn }),
        button(ctx, 'confirm-go', 'Go there', () => ctx.act.view(pending.view as ViewId)),
        button(ctx, 'cancel', 'Cancel (n)', ctx.act.cancel, { hotkey: 'n' }),
      ],
      'confirm',
    )
  }

  // One bordered card in the warning colour: the person says yes to everything in it, so it reads as a unit, not as loose lines. Its border and
  // padding take four columns, so the text inside is clipped to the narrower width.
  const inner: Ctx = { ...ctx, columns: Math.max(20, ctx.columns - 4) }
  const hasMoney = pending.note !== undefined && /money|models/i.test(pending.note)

  return ctx.kit.Box({
    key: 'confirm',
    flexDirection: 'column',
    borderStyle: 'round',
    borderColor: THEME.warn,
    paddingX: 1,
    children: [
      row(ctx, [ctx.kit.Text({ bold: true, color: THEME.warn, children: '▶ CONFIRM NEEDED' }), ctx.kit.Text({ dimColor: true, children: '  click Yes or press y' })]),
      text(inner, '─'.repeat(inner.columns), { dimColor: true }),
      text(inner, `Confirm: ${askedBy(pending)}${pending.label.replace(/\?+$/, '')}?`, { bold: true, color: THEME.warn }),
      // Wrapped, not clipped: the person says yes to the whole argv, so all of it shows (a JSON argument runs long).
      ctx.kit.Text({ dimColor: true, wrap: 'wrap', children: `runs: ${pending.shows ?? `ruflo ${pending.args.join(' ')}`}` }),
      ...(pending.note !== undefined ? [ctx.kit.Text({ wrap: 'wrap', bold: hasMoney, color: hasMoney ? THEME.bad : THEME.warn, children: `Effect: ${pending.note}` })] : []),
      ctx.kit.Box({
        flexDirection: 'row',
        marginTop: 1,
        children: [
          button(ctx, 'confirm', 'Yes, run it (y)', ctx.act.confirm, { hotkey: 'y', primary: true }),
          button(ctx, 'cancel', 'Cancel (n)', ctx.act.cancel, { hotkey: 'n' }),
          // A low-risk ruflo action may be remembered: it is not asked again (Settings lists and forgets it).
          ...(pending.rememberKey !== undefined ? [button(ctx, 'remember', `Always allow “${pending.rememberKey}”`, () => ctx.act.remember())] : []),
          // An AI terminal turn (claude -p in plan mode, codex read-only, the budget cap) may be always accepted: Settings resets it.
          ...(ctx.state.terminal.asked !== null && pending.label === ctx.state.terminal.asked.label && ctx.state.terminal.harness !== 'ruflo' ? [button(ctx, 'always', 'Always accept AI turns', () => ctx.act.settings.alwaysAccept())] : []),
        ],
      }),
    ],
  })
}

/** Views that draw the confirm themselves, under the field it came from (the pane then does not draw it above the body). */
export const INLINE_CONFIRM: ReadonlySet<string> = new Set(['missions', 'hive'])

/** True when the view draws this ask itself (under what raised it), so the pane does not also draw it at the top. */
export const confirmInline = (view: string, scope: string | undefined): boolean => (scope === 'ask' ? false : view === 'memory' ? scope?.startsWith('mem:') === true : INLINE_CONFIRM.has(view))

/** The confirm row when the pending ask came from this scope (or has none, and this is the view's default place for it). */
export function confirmHere(ctx: Ctx, scope: string, isDefault = false): RenderElement[] {
  const pending = ctx.state.pending

  if (pending === null || (pending.scope ?? (isDefault ? scope : '')) !== scope) return []

  const row = confirmRow(ctx)

  return row === null ? [] : [row]
}

