    cost: 'writes',
    argv: text => {
      const type = actionTypeOf(text)

      return type === null ? null : ['mcp', 'exec', '-t', 'policy_evaluate', '-p', JSON.stringify({ request: { identity: { id: 'ruflo-console', type: 'user' }, action: { type } } })]
    },
